#!/usr/bin/env node
/**
 * Claude Code adapter generator (DHI-526).
 * Reads adapters/claude/rule-map.yaml and writes a single root CLAUDE.md
 * from core .ai/rules sources (H2 section per mapped rule). Zero npm dependencies.
 *
 * Usage (repo root):
 *   node adapters/claude/generate.mjs
 *   node adapters/claude/generate.mjs --out /path/to/out
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const GENERATED_MARKER =
  "<!-- GENERATED by adapters/claude/generate.mjs — do not edit; re-run the generator -->";

const HOW_TO_SECTION = `## How to use prompts and skills

- Load public prompts by stable id under \`.ai/prompts/public/\` (e.g. \`eversis-implement\`).
- Load internal / EM-routed prompts under \`.ai/prompts/internal/\` when the orchestration flow requires them.
- Resolve skills via MCP (\`eversis_skills_get\` / \`eversis_skills_list\`) when available; otherwise read \`.ai/skills/<id>/SKILL.md\`.
- Do **not** expect \`.cursor/commands\` or Cursor \`@\` attachment as the only entry — those are Cursor-channel packaging.
- Prefer backend / system-layer trees for CLI work; do **not** load Cursor-specific packaging (\`.cursor/rules/*.mdc\`, slash commands) for standards — this file is the Claude Code instruction surface.
- Full ignore-file / monorepo path isolation (\`.claudeignore\`, \`claudeMdExcludes\`) is **deferred** to DHI-528–530; until then, stay in the relevant package tree and avoid unrelated frontend/tool config when possible.
`;

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ADAPTER_DIR = __dirname;
const MAP_PATH = path.join(ADAPTER_DIR, "rule-map.yaml");

function fail(message) {
  console.error(`error: ${message}`);
  process.exit(1);
}

function findRepoRoot(startDir) {
  let dir = startDir;
  for (;;) {
    if (
      fs.existsSync(path.join(dir, ".ai")) &&
      fs.existsSync(path.join(dir, "adapters"))
    ) {
      return dir;
    }
    const parent = path.dirname(dir);
    if (parent === dir) {
      fail(
        "could not find repository root (expected .ai/ and adapters/). Run from repo root.",
      );
    }
    dir = parent;
  }
}

function parseArgs(argv) {
  let outRoot = null;
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--out") {
      const next = argv[i + 1];
      if (!next || next.startsWith("-")) {
        fail("--out requires a directory path");
      }
      outRoot = path.resolve(next);
      i++;
      continue;
    }
    if (arg === "--help" || arg === "-h") {
      console.log(
        "Usage: node adapters/claude/generate.mjs [--out <dir>]\n" +
          "  Default: write CLAUDE.md at the repository root.\n" +
          "  --out: write CLAUDE.md under <dir>.",
      );
      process.exit(0);
    }
    fail(`unknown argument: ${arg}`);
  }
  return { outRoot };
}

function stripQuotes(value) {
  if (
    (value.startsWith('"') && value.endsWith('"')) ||
    (value.startsWith("'") && value.endsWith("'"))
  ) {
    return value.slice(1, -1);
  }
  return value;
}

function parseScalar(raw) {
  const value = raw.trim();
  if (value === "true") return true;
  if (value === "false") return false;
  if (value === "[]") return [];
  if (/^-?\d+$/.test(value)) return Number(value);
  return stripQuotes(value);
}

/**
 * Constrained YAML parser for Claude rule-map.yaml shape only.
 * Supports: version, rules[] with scalar keys (id, source).
 */
function parseRuleMapYaml(text) {
  const lines = text.split(/\r?\n/);
  const doc = { version: null, rules: [] };
  let currentRule = null;

  for (let i = 0; i < lines.length; i++) {
    const rawLine = lines[i];
    const line = rawLine.replace(/\s+#.*$/, "");
    if (!line.trim() || line.trim().startsWith("#")) continue;

    const indent = line.match(/^ */)[0].length;
    const trimmed = line.trim();

    if (indent === 0 && trimmed.startsWith("version:")) {
      doc.version = parseScalar(trimmed.slice("version:".length));
      continue;
    }

    if (indent === 0 && trimmed === "rules:") {
      continue;
    }

    if (indent === 2 && trimmed.startsWith("- ")) {
      currentRule = {};
      doc.rules.push(currentRule);
      const rest = trimmed.slice(2).trim();
      if (rest.includes(":")) {
        const idx = rest.indexOf(":");
        const key = rest.slice(0, idx).trim();
        const val = rest.slice(idx + 1).trim();
        if (val !== "") {
          currentRule[key] = parseScalar(val);
        }
      }
      continue;
    }

    if (!currentRule) {
      fail(`unexpected line ${i + 1}: ${rawLine}`);
    }

    if (indent === 4 && trimmed.includes(":")) {
      const idx = trimmed.indexOf(":");
      const key = trimmed.slice(0, idx).trim();
      const val = trimmed.slice(idx + 1).trim();
      currentRule[key] = parseScalar(val);
      continue;
    }

    fail(`unexpected line ${i + 1}: ${rawLine}`);
  }

  return doc;
}

function assertSafeRepoRelative(relPath, label) {
  if (!relPath || typeof relPath !== "string") {
    fail(`${label} must be a non-empty string`);
  }
  if (path.isAbsolute(relPath)) {
    fail(`${label} must be repo-relative (got absolute path): ${relPath}`);
  }
  const normalized = path.normalize(relPath);
  if (normalized.startsWith("..") || path.isAbsolute(normalized)) {
    fail(`${label} escapes repository root: ${relPath}`);
  }
  return normalized.split(path.sep).join("/");
}

function validateRule(rule, index) {
  const prefix = `rules[${index}]`;
  for (const key of ["id", "source"]) {
    if (rule[key] === undefined || rule[key] === null || rule[key] === "") {
      fail(`${prefix}: missing required field "${key}"`);
    }
  }
  rule.source = assertSafeRepoRelative(String(rule.source), `${prefix}.source`);
  for (const banned of ["globs", "alwaysApply", "description", "output"]) {
    if (Object.prototype.hasOwnProperty.call(rule, banned)) {
      fail(
        `${prefix} (${rule.id}): field "${banned}" is Cursor packaging — omit from Claude rule-map`,
      );
    }
  }
}

function resolveClaudeMdPath(repoRoot, outRoot) {
  if (!outRoot) {
    return path.join(repoRoot, "CLAUDE.md");
  }
  return path.join(outRoot, "CLAUDE.md");
}

function buildClaudeMarkdown(repoRoot, rules) {
  const parts = [
    "# Agent Collections (Claude Code)",
    "",
    GENERATED_MARKER,
    "",
    HOW_TO_SECTION.trimEnd(),
    "",
  ];

  for (const rule of rules) {
    const sourceAbs = path.join(repoRoot, rule.source);
    if (!fs.existsSync(sourceAbs)) {
      fail(`source not found for ${rule.id}: ${rule.source}`);
    }
    const body = fs.readFileSync(sourceAbs, "utf8").replace(/^\uFEFF/, "");
    parts.push(`## ${rule.id}`);
    parts.push("");
    parts.push(body.replace(/\s+$/, ""));
    parts.push("");
  }

  return `${parts.join("\n").replace(/\s+$/, "")}\n`;
}

function writeClaudeMd(repoRoot, outRoot, rules) {
  const content = buildClaudeMarkdown(repoRoot, rules);
  const destAbs = resolveClaudeMdPath(repoRoot, outRoot);
  fs.mkdirSync(path.dirname(destAbs), { recursive: true });

  try {
    fs.lstatSync(destAbs);
    fs.unlinkSync(destAbs);
  } catch (err) {
    if (err.code !== "ENOENT") throw err;
  }

  fs.writeFileSync(destAbs, content, "utf8");
  return destAbs;
}

function main() {
  const { outRoot } = parseArgs(process.argv.slice(2));
  const repoRoot = findRepoRoot(process.cwd());

  if (!fs.existsSync(MAP_PATH)) {
    fail(`rule map not found: ${MAP_PATH}`);
  }

  const map = parseRuleMapYaml(fs.readFileSync(MAP_PATH, "utf8"));
  if (map.version !== 1) {
    fail(`unsupported rule-map version: ${map.version} (expected 1)`);
  }
  if (!Array.isArray(map.rules) || map.rules.length === 0) {
    fail("rule-map has no rules");
  }

  map.rules.forEach(validateRule);

  const dest = writeClaudeMd(repoRoot, outRoot, map.rules);
  console.log(`generated Claude Code instructions:`);
  console.log(`  ${path.relative(process.cwd(), dest) || dest}`);
  console.log(`  (${map.rules.length} rule section(s))`);
}

main();
